[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RepositoryRoot,[Parameter(Mandatory=$true)][string]$ReaderPath,[Parameter(Mandatory=$true)][string]$FixtureManifestPath,[Parameter(Mandatory=$true)][string]$OutputRoot,[string[]]$CaseNames=@())
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$m=Get-Content -LiteralPath $FixtureManifestPath -Raw|ConvertFrom-Json
. (Join-Path $RepositoryRoot 'scripts/chunk7/Test-Chunk7OrdinaryEvidence.ps1') -RepositoryRoot $RepositoryRoot -ReaderDirectory (Join-Path $RepositoryRoot 'scripts/runtime') -FixturesOnly
. $m.choiceHelper.path;. $ReaderPath;. $m.builder.path
$output=Assert-KmcChildPath $OutputRoot (Join-Path (Get-KmcLabRoot) 'analysis-cache') 'generated assisted complete reader checks'
if(Test-Path -LiteralPath $output){throw 'Preserve prior complete reader test output.'};[void][IO.Directory]::CreateDirectory($output)
$clock=[Diagnostics.Stopwatch]::StartNew()
foreach($p in @($m.host,$m.core,$m.choiceHelper,$m.builder)){if((Get-KmcSha256 $p.path)-cne$p.sha256-or(Get-Item -LiteralPath $p.path).Length-ne$p.length){throw 'Complete reader generated fixture input changed.'}}
$script:hostFragment=Read-KmcJson $m.host.path;$script:coreFragment=Read-KmcJson $m.core.path
$script:passed=0;$script:failed=0;$cases=[Collections.Generic.List[object]]::new()
function Hash-CompositionText([string]$Text){$sha=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($sha.ComputeHash([Text.UTF8Encoding]::new($false,$true).GetBytes($Text))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Run-CompositionCase([string]$Name,[bool]$Accepted,[scriptblock]$Action){
 if($CaseNames.Count-gt0-and$Name-cnotin$CaseNames){return}
 $errorText=$null;$acceptedNow=$true;$stack=$null;$fixtureReady=$false
 try{$f=New-AssistedCompositionFixture;$fixtureReady=$true;&$Action $f}catch{$acceptedNow=$false;$errorText=$_.Exception.Message;$stack=$_.ScriptStackTrace}
 $ok=$fixtureReady-and$acceptedNow-eq$Accepted;if($ok){$script:passed++}else{$script:failed++}
 $cases.Add([pscustomobject]@{name=$Name;status=$(if($ok){'PASS'}else{'FAIL'});expectedAccepted=$Accepted;actualAccepted=$acceptedNow;fixtureReady=$fixtureReady;error=$errorText;stack=$stack})
 Write-Host ($(if($ok){'PASS '}else{'FAIL '})+$Name+$(if(-not$ok-and$errorText){': '+$errorText}else{''}))
}
function Probe-Composition($f){$o=$f.artifact.observations;$labels=[Collections.Generic.HashSet[int]]::new();foreach($id in $o.identityRegistry.retainedIds){[void]$labels.Add($id)};$proof=Get-KmcChunk7OrdinaryChoiceProof $f.request.runId ([pscustomobject]@{existingActorId=$o.fieldWorld.mainActorId;minimumRangerLevel=4}) $false @($o.beforeSetup.party.id) $o.choices $o.setup.experience.after.money $o.builderComplete;Assert-KmcAssistedOrdinaryProbe $o $proof $labels}
Run-CompositionCase 'actual assisted prepared Auto2 then completed Auto1' $true {param($f)Probe-Composition $f}
Run-CompositionCase 'assisted prepared Auto1 is not the selected staging descriptor' $false {param($f)$f.artifact.observations.ordinaryProbe.events[-1].saveLeaf='Auto_1.zks';Probe-Composition $f}
Run-CompositionCase 'complete controlled three-write composition' $true {param($f)Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'native Ranger choices with initial Auto and final Manual' $true {param($f)$two=New-AssistedTwoWriteBuiltFixture;Assert-KmcChunk7AssistedFixtureEvidence $two.request $two.artifact}
Run-CompositionCase 'two-write Ranger build refuses missing choice proof' $false {param($f)$two=New-AssistedTwoWriteBuiltFixture;$two.artifact.observations.choices=@();Assert-KmcChunk7AssistedFixtureEvidence $two.request $two.artifact}
Run-CompositionCase 'two-write Ranger build refuses invented intermediate Auto' $false {param($f)$two=New-AssistedTwoWriteBuiltFixture;$two.artifact.observations.nativeWrites[0].autoLevelup=$true;Assert-KmcChunk7AssistedFixtureEvidence $two.request $two.artifact}
Run-CompositionCase 'missing native companion rank refused' $false {param($f)$o=$f.artifact.observations;foreach($w in @($o.fieldWorld,$o.savedWorld,$o.settledWorld)){$a=@($w.party|Where-Object id -CEQ $o.fieldWorld.mainActorId)[0];$a.features=@($a.features|Where-Object guid -CNE '1670990255e4fe948a863bafd5dbda5d')};$a=@($o.afterSetupActors|Where-Object id -CEQ $o.fieldWorld.mainActorId)[0];$a.features=@($a.features|Where-Object guid -CNE '1670990255e4fe948a863bafd5dbda5d');Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'coordinated native character omission refused' $false {param($f)$o=$f.artifact.observations;$main=$o.fieldWorld.mainActorId;$o.nativeProfileInventory.ordinaryAcquisitionPrerequisites.nativePartyCharacterIds=@($main);$o.fixtureReadiness.staticPartyFacts.characters=@($o.fixtureReadiness.staticPartyFacts.characters|Where-Object actorId -CEQ $main);Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'same-total readiness class substitution refused' $false {param($f)$f.artifact.observations.fixtureReadiness.mainProgression.classes[0].classGuid='edededededededededededededededed';Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'field feature cannot alias Game owner' $false {param($f)$o=$f.artifact.observations;foreach($w in @($o.fieldWorld,$o.savedWorld,$o.settledWorld)){$w.party[0].features[0].object=$o.fieldWorld.game};$o.afterSetupActors[0].features[0].object=$o.fieldWorld.game;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}

Run-CompositionCase 'backdated story before native campaign refused' $false {param($f)$o=$f.artifact.observations;$o.setup.story.lastObserved.frame=1;$o.setupAtCleanup.story.lastObserved.frame=1;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'initial main descriptor cannot be replaced during story' $false {param($f)$o=$f.artifact.observations;$o.identityRegistry.retainedIds+=77770006;$o.initialWorld.party[0].descriptor=77770006;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'foreign pending sidecar refused' $false {param($f)$f.request.scenario='export-mounted-contracts';Assert-KmcChunk7AssistedFixtureArtifact $f.request ([pscustomobject]@{artifacts=@([pscustomobject]@{kind='chunk7-assisted-fixture-cleanup-pending';relativePath='chunk7-assisted-fixture-cleanup-pending.json'})}) 'FAIL'}
Run-CompositionCase 'malformed selected pending-only sidecar refused' $false {param($f)function Read-KmcChunk7ManifestArtifact {param($Request,$Manifest,$Leaf,$Kind)[pscustomobject]@{schemaVersion=1;evidenceKind='wrong';status='FAIL';observations=[pscustomobject]@{};errors=@()}};Assert-KmcChunk7AssistedFixtureArtifact $f.request ([pscustomobject]@{artifacts=@([pscustomobject]@{kind='chunk7-assisted-fixture-cleanup-pending';relativePath='chunk7-assisted-fixture-cleanup-pending.json'})}) 'FAIL'}


Run-CompositionCase 'complete controlled two-write already-trained composition' $true {param($f)$two=New-AssistedTwoWriteFixture;Assert-KmcChunk7AssistedFixtureEvidence $two.request $two.artifact}
Run-CompositionCase 'no-levelup branch rejects invented native choices' $false {param($f)$two=New-AssistedTwoWriteFixture;$two.artifact.observations.choices=@($f.artifact.observations.choices[0]);Assert-KmcChunk7AssistedFixtureEvidence $two.request $two.artifact}
Run-CompositionCase 'main initial view cannot be absent' $false {param($f)$f.artifact.observations.initialWorld.party[0].view=0;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'story observed after setup began refused' $false {param($f)$o=$f.artifact.observations;$o.setup.story.lastObserved.frame=500;$o.setupAtCleanup.story.lastObserved.frame=500;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'zero native companion rank refused' $false {param($f)$o=$f.artifact.observations;foreach($w in @($o.fieldWorld,$o.savedWorld,$o.settledWorld)){($w.party[0].features|Where-Object guid -CEQ '1670990255e4fe948a863bafd5dbda5d').rank=0};($o.afterSetupActors[0].features|Where-Object guid -CEQ '1670990255e4fe948a863bafd5dbda5d').rank=0;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'pet cannot replace a native character in both derived rosters' $false {param($f)$o=$f.artifact.observations;$pet=@($o.fieldWorld.party|Where-Object masterId -CEQ $o.fieldWorld.mainActorId)[0];$o.nativeProfileInventory.ordinaryAcquisitionPrerequisites.nativePartyCharacterIds[1]=$pet.id;$o.fixtureReadiness.staticPartyFacts.characters[1].actorId=$pet.id;$o.fixtureReadiness.staticPartyFacts.characters[1].blueprintGuid=$pet.blueprint;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'authority generation rebound refused' $false {param($f)$f.artifact.observations.cleanup.authority.generation++;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'unfinished native worker refused' $false {param($f)$f.artifact.observations.manualProbe.events[4].workerCompleted=$false;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'unreleased cleanup identity custody refused' $false {param($f)$f.artifact.observations.cleanup.identityRegistryReleased=$false;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'final Manual cannot substitute an unobserved descriptor' $false {param($f)$f.artifact.observations.finalManual.preparedDescriptor=77770001;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'assisted setup cannot claim ordinary progression' $false {param($f)$f.artifact.observations.ordinaryProgressionProven=$true;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'native Manual numbering cannot drift from reservation' $false {param($f)$f.artifact.observations.nativeNumbering.number++;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'Main XP assistance cannot invent retained pet state' $false {param($f)$o=$f.artifact.observations;foreach($s in @($o.setup.experience.before,$o.setup.experience.after,$o.setupAtCleanup.experience.before,$o.setupAtCleanup.experience.after)){$s.isPet=$true};Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'choice admission Ranger rank must bind observed native class' $false {param($f)$f.artifact.observations.choices[0].rangerLevel=2;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'choice final Ranger rank must bind observed native class' $false {param($f)$o=$f.artifact.observations;$o.builderComplete.rangerLevel=5;$o.choices[-1].actor.rangerLevel=5;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'valid pending custody remains readable only as FAIL' $true {param($f)$pending=Copy-O $f.artifact;$pending.evidenceKind='chunk7-assisted-fixture-cleanup-pending';$pending.status='FAIL';$pending.errors=@('Native worker retains custody');$pending.observations=[pscustomobject]@{cleanupCustodyRetained=$true;cleanupPendingAtHostBoundary=$true;reason='Native worker retains custody';authority=(Copy-O $f.artifact.observations.fieldWorld.authority)};Assert-KmcChunk7AssistedPendingArtifact $f.request $pending}
Run-CompositionCase 'pending before native binding retains nullable authority' $true {param($f)$pending=Copy-O $f.artifact;$pending.evidenceKind='chunk7-assisted-fixture-cleanup-pending';$pending.status='FAIL';$pending.errors=@('Preflight cleanup retains custody');$a=Copy-O $f.artifact.observations.before.authority;foreach($key in @('root','phase','maximumNativeLoads','maximumNativeWrites','admittedNativeLoads','admittedNativeWrites','freezeCount','windowOpen','manualNumber','reservationCount','levelupWrites')){$a.$key=$null};$a.generation=0;$pending.observations=[pscustomobject]@{cleanupCustodyRetained=$true;cleanupPendingAtHostBoundary=$true;reason='Preflight cleanup retains custody';authority=$a};Assert-KmcChunk7AssistedPendingArtifact $f.request $pending}


Run-CompositionCase 'choice descriptor must bind retained native main descriptor' $false {param($f)$o=$f.artifact.observations;function Shift-ChoiceDescriptor($v){if($null-eq$v-or$v-is[string]-or$v-is[ValueType]){return};if($v-is[Array]){foreach($i in $v){Shift-ChoiceDescriptor $i};return};foreach($p in $v.PSObject.Properties){if($p.Name-ceq'descriptorObject'){$p.Value=104}else{Shift-ChoiceDescriptor $p.Value}}};Shift-ChoiceDescriptor $o.choices;Shift-ChoiceDescriptor $o.builderComplete;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}


Run-CompositionCase 'descriptor bridge cannot point to unrelated actor descriptor' $false {param($f)$o=$f.artifact.observations;$o.ordinaryIdentityBridge.roles.descriptor.host=$o.fieldWorld.party[1].descriptor;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}
Run-CompositionCase 'descriptor bridge must stay within retained host labels' $false {param($f)$f.artifact.observations.ordinaryIdentityBridge.roles.descriptor.host=12345678;Assert-KmcChunk7AssistedFixtureEvidence $f.request $f.artifact}

if($cases.Count-eq0){throw 'Complete reader selected zero cases.'}
$receipt=[ordered]@{schemaVersion=1;kind='assisted-generated-composition';status=$(if($script:failed-eq0){'PASS'}else{'FAIL'});passed=$script:passed;failed=$script:failed;durationSeconds=$clock.Elapsed.TotalSeconds;nativeInvoked=$false;installedOrProtectedArchiveReads=0;readerSha256=(Get-KmcSha256 $ReaderPath);fixtureManifestSha256=(Get-KmcSha256 $FixtureManifestPath);scope='Controlled complete generated evidence using actual host/core formatter shapes and explicitly substituted native callbacks/profiles/progression; no native qualification';cases=$cases.ToArray()}
[IO.File]::WriteAllText((Join-Path $output 'receipt.json'),($receipt|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))
Write-Host ('ASSISTED COMPOSITION PASS='+$script:passed+' FAIL='+$script:failed)
if($script:failed-ne0){$global:LASTEXITCODE=1}else{$global:LASTEXITCODE=0}
